from datetime import UTC, datetime
from typing import Literal
from uuid import UUID, uuid7

from pydantic import BaseModel, Field

from api.llm.types import Effort, StopReason, Usage


def _now() -> datetime:
    return datetime.now(UTC)


class ChatSession(BaseModel):
    # Generated by the client for a new chat; the session is created on its first message.
    id: UUID
    title: str
    created_at: datetime = Field(default_factory=_now)


class ChatMessage(BaseModel):
    id: str = Field(default_factory=lambda: str(uuid7()))
    session_id: UUID
    role: Literal["user", "assistant"]
    content: str = ""
    reasoning: str = ""
    # How long the model reasoned: set when the answer starts, or when a reply ends
    # without one. None while still reasoning, and for replies with no reasoning.
    reasoning_ms: int | None = None
    model: str | None = None
    # None while an assistant message is still streaming.
    stop_reason: StopReason | None = None
    error: str | None = None
    usage: Usage | None = None
    # Count of deltas folded into content/reasoning, so clients that join mid-stream can
    # skip deltas already included in their snapshot.
    seq: int = 0
    created_at: datetime = Field(default_factory=_now)


class SessionUpdate(BaseModel):
    title: str = Field(min_length=1, max_length=200)


class JoinPayload(BaseModel):
    session_id: UUID


class SendPayload(BaseModel):
    session_id: UUID
    input: str = Field(min_length=1, max_length=100_000)
    model: str
    effort: Effort | None = None


class CancelPayload(BaseModel):
    session_id: UUID
